def extend(catalogues):
    for code,row in ROWS.items():
        values=row.split('|')
        if len(values)!=len(KEYS): raise ValueError(f'Invalid 0.8 catalogue {code}: {len(values)}')
        catalogues[code].update(zip(KEYS,values))
